questions.solution:
function kindOf(names) {
  const parts = [];
  for (const name of names) {
    parts.push(`${name}:${typeof globalThis[name]}`);
  }
  return parts.join(" ");
}

console.log(kindOf(["Math", "JSON", "setTimeout", "NotReal"]));
